def translations():
    result = {}
    for code, row in RAW.items():
        values = row.split("|")
        if len(values) != len(FIELDS):
            raise ValueError(f"{code}: expected {len(FIELDS)} fields, got {len(values)}")
        result[code] = dict(zip(FIELDS, values))
    return result
